    'd.settings-more.aApps': 'Ʋu Hame ƒe apps le bar si le miame la me: Biblia, Sabat Suku, Hadzigbalẽ, Pod, Hamewo, Habɔbɔwo kple Erha katã le afi ma.',
    'd.settings-more.qPlus': 'Nu ka nye Community Plus?',
