    'd.settings-more.aTick': 'Blue tick la ɖenɛ fiana be akɔnta la nye ame si wògblɔ be yenye vavã. Femaxee wònye eye womate ŋu aƒlee o: bia tso Community Plus ƒe axa dzi kple ID ƒe foto kple selfie. Admin aɖe alé ŋku ɖe wo ŋu, eye woatutu fotoawo ne wowu wò biabia la ŋu nya gbɔ kpɔkpɔ nu.',
    'd.settings-more.aAds': 'Àte ŋu aɖe gbeƒã wò post ɖesiaɖe tso eƒe menu me alo tso Dɔwɔwɔ ƒe dashboard me: tia ŋkeke nenie eye nàxe fe kple card, eye wòadze abe Sponsored ene le Na wò kple Di ƒe tame. Gaƒoƒowo nɔa wò profile dzi, eye nunanawo yina tẽ ɖe wò ŋutɔ wò ga xɔxɔ ƒe akɔnta me.',
