    'd.settings-more.agoWeeks': 'wiki {count} zilizopita',
    'd.settings-more.clickStar': 'Bofya nyota',
    'd.settings-more.gladToast': 'Asante! Tunafurahi sana kwamba unafurahia Community.',
    'd.settings-more.yourReview': 'Maoni yako',
    'd.settings-more.yourIdea': 'Wazo lako',
    'd.settings-more.sending': 'Inatuma…',
