    'd.settings-more.aTick': '파란색 인증 배지는 계정이 본인임을 보여 줘요. 무료이며 구매할 수 없어요. Community Plus 페이지에서 신분증 사진과 셀카로 요청하세요. 관리자가 확인하고, 요청이 결정되면 사진은 삭제돼요.',
    'd.settings-more.aAds': '내 게시물은 메뉴나 프로페셔널 대시보드에서 홍보할 수 있어요. 기간을 정하고 카드로 결제하면 추천과 탐색 맨 위에 스폰서로 표시돼요. 모금 활동은 프로필에 표시되고, 기부금은 내 지급 계좌로 바로 들어가요.',
