    'd.settings-more.aProfile': '名前、ユーザーネーム、写真、自己紹介は「設定」→「プロフィールを編集」にあります。2つ目のアカウントを追加するには、「その他」→「アカウントを切り替え」を開いてログインします。1台のコンピューターに最大5つのアカウントを置き、ログアウトせずに切り替えられます。',
